	We recall (one of) the construction(s) of the Cassels-Weil pairing (for semi-abelian varieties). We will take the liberty to identify, with a slight abuse of notation, a semi-abelian variety $Y$, defined over an algebraically closed field $\bar{k}$ with the $\Gamma_k$-group $Y(\bar{k})$:

	\begin{lemma}\label{Lem:Cassels_Weil}
		Let $S$ be a semiabelian variety over a field $k$, $e$ be the identity element in $S$, $A\defeq S^{ab}$ and $T \defeq \mathrm{Ker}(S \rightarrow A)$. We denote by $Z(\overline{S})$ the degree $0$ zero-cycles on $\overline{S}\defeq S \times_k \bar{k}$, and by $Z^0(\overline{S})$ the degree $0$ zero-cycles $\sum_{i=0}^N n_i(P_i)$ such that $\prod P_i^{n_i}=e \in \overline{S}$. 
		Moreover, let:
		\begin{equation}
		Z_{ab}(\overline{S})\defeq \faktor{Z(\overline{S})}{<(t\cdot P)- (P) -(t) + (e), \ t \in T(\overline{k}), \ P 	\in SA_G(\overline{k})>}
		\end{equation}
		There is a natural morphism $Z(\overline{S})\rightarrow \overline{S}$ defined by $\sum_{i=0}^N n_i(P_i) \mapsto \prod P_i^{n_i} \in \overline{S}$, which factors through $Z_{ab}(\overline{S})$. We define then
		\begin{equation}
		Z^0_{ab}(\overline{S})\defeq \mathrm{Ker} (Z_{ab}(\overline{S})\rightarrow \overline{S})\cong Z^0(A).
		\end{equation}
		The following morphisms of complexes are quasi-isomorphisms:




		\[
