		\[
		[\bar{k}(S)_{vert}^*/\bar{k}^*\rightarrow \Div^0 (A)] \rightarrow [\widehat{T}\rightarrow A^*=\Pic^0(A)],
		\]
		\[
		(f,D) \longmapsto (\restricts{f}{T}, [D]).
		\]
		The Cassels-Tate pairing $[\widehat{T_{G}}\rightarrow A^*] \otimes^{L}[0 \rightarrow \overline{S}]\rightarrow \mathbb{G}_m[-1]\defeq [\bar{k}^*][-1]$ is then induced by the following pairing:

		\begin{equation}\label{Eq:pairing_casselsTate}
				[\bar{k}(S)_{vert}^*/\bar{k}^*\rightarrow \Div^0 (A)] \otimes [Z_{ab}^0(\overline{S})\rightarrow Z_{ab}(\overline{S})]  \rightarrow \mathbb{G}_m[-1],
		\end{equation}
		where
		\[
		\bar{k}(S)_{vert}^*/\bar{k}^* \otimes Z(\overline{S}) \rightarrow \bar{k}^*
		\]
		is the pairing induced by the evaluation of a function, and:
		\[
		\Div^0 (\overline{A}) \otimes Z^0(\overline{S}) \rightarrow \bar{k}^*
		\]
		is defined as:
		\[
		\Div^0 (\overline{A}) \otimes Z^0(\overline{S}) \rightarrow \Div^0 (\overline{A}) \otimes Z^0(\overline{A}) \rightarrow  \bar{k}^*,
		\]
		where the last arrow is defined as in \cite[Sec. 3.2]{Cassels_Tate}.
	\end{lemma}

	\begin{proof}
		When $S$ is an abelian variety, this is well-known ( see \cite[Sec. 3]{Cassels_Tate}). In the general case it follows by devissage.











	\end{proof}

	We have the following quasi-isomorphism:



	\begin{equation}\label{Table3}
