	{C'_X}^d \arrow[u, "\eta"]: &\overline{k}(SA_G)^*_{vert}/\overline{k}^* \arrow[r] \arrow[u] & \Div^0(\overline{G}^{ab})\oplus \widehat{T_{G^{\mathrm{sc}}}}\oplus \widehat{Z_{H^{red}}} \arrow[r] \arrow[u]                                   & \widehat{Z_{H^{\mathrm{sc}}}} \arrow[u]
	\end{tikzcd},
