	\begin{equation}\label{Table4}
	\begin{tikzcd}
	C'_X \arrow[d, "v"]: &Z_{H^{\mathrm{sc}}} \arrow[r] \arrow[d] & Z_{\bar{H}^{\mathrm{red}}}\oplus T_{G^{\mathrm{sc}}}\oplus Z^0_{ab}(SA_G) \arrow[r] \arrow[d] & Z_{ab}(SA_G) \arrow[d] \\
