	\end{equation*}


	This concludes the proof of this lemma.






\end{proof}










To use (\ref{Eq:abelian}) for our comparison purposes we make a specific choice of $\tilde{\chi}_{\sigma,\eta}$, that will lead us to identity (\ref{Eq:ab2}) below.

We notice that, since $\overline{SA_{G}}\rightarrow \overline{G^{ab}}$ defines a $\mathbb{G}_m^n$-torsor (for some $n \geq 0$)  on $\overline{G^{ab}}$ that is Zariski locally trivial, there exists, for each $\sigma \in \Gamma_k$, a $g_{\sigma} \in \overline{k}(SA_G)^*$ such that $g_{\sigma}(t)=(f_{\sigma})_t(1), \ \forall t \in T_G(\overline{k})$ and $\div(g_{\sigma})=D_{\sigma}-E_{\sigma}$, where $E_{\sigma} \in \pi^*\Div(\overline{G^{ab}})$. 

We now define $\tilde{\chi}_{\sigma,\eta}\defeq f_{\sigma,\eta}\cdot (\partial g_{\sigma})^{-1}$. We notice that, by (\ref{Cocy3}), $f_{\sigma,\eta}\cdot (\partial g_{\sigma})^{-1}$ restricts to $\chi_{\sigma,\eta}^{-1}$ on $\overline{T_G} \subset \overline{SA_G}$.


We have that, for any $t \in T(\bar{k})$, $\div(t^*g_{\sigma}/g_{\sigma})=t^*D_{\sigma}-D_{\sigma}=\div((f_{\sigma})_t)|_{SA_G}$
(since $t^*E_{\sigma}=E_{\sigma}$). From this we deduce that

\[t^*g_{\sigma}/g_{\sigma}=(f_{\sigma})_t|_{SA_G} \cdot (\tilde{\chi}_{\sigma})_t,\]

for some $(\tilde{\chi}_{\sigma})_t(\star) \in \overline{k}(T_G\times SA_G)^*$ such that $(\tilde{\chi}_{\sigma})_t \in \overline{k}[SA_G]^*$ for every $t \in T(\bar{k})$ where the specialization makes sense. One may easily see that $(\tilde{\chi}_{\sigma})_1=1$ and $(\tilde{\chi}_{\sigma})_1(\star)=1$, from which it follows that $(\tilde{\chi}_{\sigma})_t = 1 \in \overline{k}(T_G\times SA_G)^*$.




Noticing that $\partial g_{\sigma}(\xi)= \partial (g_{\sigma}(\xi))\cdot \leftidx{^\sigma}{g_{\eta}}(\leftidx{^\sigma}{\xi})^{-1}\cdot \leftidx{^\sigma}{g_{\eta}}(\xi)$, we can rewrite $\widetilde{\chi}_{\sigma,\eta}(\xi)$, up to a $2$-coborder as follows (we remind the reader on Notation \ref{Not:Delta}):

\begin{align}
	\widetilde{\chi}_{\sigma,\eta}(\xi)^{-1}
	&=f_{\sigma,\eta}(\xi)\cdot \leftidx{^\sigma}{g_{\eta}}(\leftidx{^\sigma}{\xi})\cdot \leftidx{^\sigma}{g_{\eta}}(\xi)^{-1}=f_{\sigma,\eta}(\xi)\cdot (\leftidx{^\sigma}{f_{\eta}})_{(\partial \xi)^{-1}}(\xi)^{-1}

	\nonumber \\
	&=
	f_{\sigma,\eta}(\xi)\cdot (\leftidx{^\sigma}{f_{\eta}})_{\partial \xi}(\xi)^{-1}

	\triangleq f_{\sigma,\eta}(\xi)\cdot (\leftidx{^\sigma}{f_{\eta}})_{\partial \xi}(\xi)^{-1}. \label{Eq:ab2}
\end{align}

\smallskip


To (hopefully) smoothen the computation of the LHS of (\ref{Eq:2pairings}) we introduce a second Galois pseudo-action (as defined in Section \ref{Sec:notation}) on $\bar{k}(H^{sc})^*$ and $\Div(H^{sc})$. It is defined as follows:

\begin{equation}\label{Eq:Pseudo_action}
